    }
  }

  [data-settings-page-scroll] div.settings-search-target-pulse,
  [data-settings-page-scroll] section.settings-search-target-pulse > div:first-child {
    animation: settings-search-target-pulse 650ms ease-in-out 2;
    border-radius: 0.75rem;
  }

  /* The pulse is the destination indicator; without it (reduced motion), the
     focus outline takes over, so exactly one indicator shows at a time. */
  [data-settings-page-scroll] .settings-search-target-pulse:focus {
    outline: none;
  }

  [data-preview-panel-mode="inline"] [data-right-panel-surface-content] [data-surface-subheader] {
    height: calc(var(--spacing) * 7);
    min-height: calc(var(--spacing) * 7);
    margin-bottom: calc(var(--spacing) * 3);
    border-bottom-color: transparent;
  }

  .chat-content-lane {
    margin-inline: auto;
    width: 100%;
    min-width: 0;
    max-width: var(--chat-content-max-width);
  }

  .messages-timeline-row-frame {
    padding-inline: 0;
  }

  .settings-slider {
    --settings-slider-progress: 0%;
    --settings-slider-fill-offset: 0.5rem;
    --settings-slider-fill-position: calc(
      var(--settings-slider-progress) + var(--settings-slider-fill-offset)
    );
    appearance: none;
    height: 1.5rem;
    background: transparent;
    cursor: pointer;
  }

  .settings-slider::-webkit-slider-runnable-track {
    height: 0.375rem;
    border-radius: 9999px;
    background: linear-gradient(
      to right,
      var(--primary) 0 var(--settings-slider-fill-position),
      color-mix(in srgb, var(--contrast-muted-foreground) 22%, transparent)
        var(--settings-slider-fill-position) 100%
    );
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--contrast-border) 55%, transparent);
  }

  .settings-slider::-moz-range-track {
    height: 0.375rem;
    border-radius: 9999px;
    background: color-mix(in srgb, var(--contrast-muted-foreground) 22%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--contrast-border) 55%, transparent);
  }

  .settings-slider::-moz-range-progress {
    height: 0.375rem;
    border-radius: 9999px;
    background: var(--primary);
  }

  .settings-slider::-webkit-slider-thumb {
    appearance: none;
    width: 1rem;
    height: 1rem;
    margin-top: -0.3125rem;
    border: 2px solid var(--primary);
    border-radius: 9999px;
    background: var(--background);
    box-shadow: 0 1px 2px color-mix(in srgb, var(--contrast-foreground) 12%, transparent);
    transition:
      transform 120ms ease,
      box-shadow 120ms ease;
  }

  .settings-slider::-moz-range-thumb {
    width: 1rem;
    height: 1rem;
    border: 2px solid var(--primary);
    border-radius: 9999px;
    background: var(--background);
    box-shadow: 0 1px 2px color-mix(in srgb, var(--contrast-foreground) 12%, transparent);
    transition:
      transform 120ms ease,
      box-shadow 120ms ease;
  }

  .settings-slider:hover::-webkit-slider-thumb {
    transform: scale(1.08);
    box-shadow: 0 1px 3px color-mix(in srgb, var(--contrast-foreground) 20%, transparent);
  }

  .settings-slider:hover::-moz-range-thumb {
    transform: scale(1.08);
    box-shadow: 0 1px 3px color-mix(in srgb, var(--contrast-foreground) 20%, transparent);
  }

  .settings-slider:active::-webkit-slider-thumb {
    transform: scale(0.94);
  }

  .settings-slider:active::-moz-range-thumb {
    transform: scale(0.94);
  }

  .settings-slider:focus-visible {
    outline: none;
  }

  .settings-slider:focus-visible::-webkit-slider-thumb {
    box-shadow:
      inset 0 0 0 1px var(--background),
      inset 0 0 0 3px var(--ring);
  }

  .settings-slider:focus-visible::-moz-range-thumb {
    box-shadow:
      inset 0 0 0 1px var(--background),
      inset 0 0 0 3px var(--ring);
  }

  @media (forced-colors: active) {
    .settings-slider {
      appearance: auto;
      accent-color: Highlight;
    }

    .settings-slider::-webkit-slider-runnable-track,
    .settings-slider::-webkit-slider-thumb {
      all: revert;
    }

    .settings-slider::-moz-range-track,
    .settings-slider::-moz-range-progress,
    .settings-slider::-moz-range-thumb {
      all: revert;
    }
  }
}

/* Safe-area inset utilities for surfaces that opt into edge-to-edge rendering.
   Insets resolve to 0 when the browser already constrains the layout viewport
   to the safe area. */
@utility pt-safe {
  padding-top: max(env(safe-area-inset-top), 0px);
}
@utility pb-safe {
  padding-bottom: max(env(safe-area-inset-bottom), 0px);
}
@utility pl-safe {
  padding-left: max(env(safe-area-inset-left), 0px);
}
@utility pr-safe {
  padding-right: max(env(safe-area-inset-right), 0px);
}

/* Grain texture for chrome surfaces that float above the body (see the
   --surface-grain note). Layered over the element's background-color, so it
   composes with bg-* utilities. */
@utility surface-grain {
  background-image: var(--surface-grain);
  background-repeat: repeat;
  background-size: var(--surface-grain-size);
}

/* Suppress all transitions during theme changes */
.no-transitions,
.no-transitions *,
.no-transitions *::before,
.no-transitions *::after {
  transition-duration: 0s !important;
  animation-duration: 0s !important;
}

:root {
  color-scheme: light;
  --radius: 0.5rem;
  --background: var(--color-zinc-25);
  --app-chrome-background: var(--background);
  --toolbar-background: var(--app-chrome-background);
  --toolbar-foreground: var(--foreground);
  --toolbar-border: var(--border);
  --toolbar-control: var(--popover);
  --toolbar-control-foreground: var(--foreground);
  --toolbar-control-hover: var(--accent);
  --surface-raised: color-mix(in srgb, var(--card) 20%, transparent);
  --foreground: var(--color-zinc-900);
  --card: var(--color-white);
  --card-foreground: var(--color-zinc-900);
  --popover: var(--color-white);
  --popover-foreground: var(--color-zinc-900);
  --primary: oklch(0.488 0.217 264);
  --primary-foreground: var(--color-white);
  --secondary: var(--color-zinc-50);
  --secondary-foreground: var(--color-zinc-800);
  --muted: var(--color-zinc-50);
  --muted-foreground: var(--color-zinc-500);
  --placeholder: var(--muted-foreground);
  --secondary-label: var(--muted-foreground);
  --icon-muted: var(--muted-foreground);
  /* One step past the accent, so a user turn stands off the near-white canvas. */
  --message-surface: color-mix(in srgb, var(--color-zinc-200) 55%, var(--color-zinc-100));
  --message-foreground: var(--foreground);
  --message-action: var(--primary);
  --message-action-foreground: var(--primary-foreground);
  --message-action-hover: color-mix(in srgb, var(--primary) 90%, var(--background));
  --accent: var(--color-zinc-100);
  --accent-foreground: var(--color-zinc-900);
  --error: var(--color-red-500);
  --error-foreground: var(--color-red-700);
  --tool-error-icon: var(--error);
  --error-surface: color-mix(in srgb, var(--error) 8%, transparent);
  --destructive: var(--error);
  --border: var(--color-zinc-200);
  --input: var(--color-zinc-300);
  --ring: var(--primary);
  --destructive-foreground: var(--error-foreground);
  --info: var(--color-blue-500);
  --info-foreground: var(--color-blue-700);
  /* Messages from a guest link, and the sidebar Request status. */
  --guest: var(--color-fuchsia-500);
  --guest-foreground: var(--color-fuchsia-600);
  --guest-surface: color-mix(in srgb, var(--guest) 14%, var(--message-surface));
  --success: var(--color-emerald-500);
  --success-foreground: var(--color-emerald-700);
  --warning: var(--color-amber-500);
  --warning-foreground: var(--color-amber-700);
  --warning-surface: color-mix(in srgb, var(--warning) 8%, transparent);
  --update: var(--primary);
  --update-foreground: var(--primary);
  /* Keep every sidebar primitive on the same light surface hierarchy, including
     portaled mobile sheets and settings navigation outside the app sidebar. */
  --sidebar: var(--color-zinc-50);
  --sidebar-foreground: var(--foreground);
  --sidebar-muted-foreground: var(--muted-foreground);
  --sidebar-control-surface: var(--color-zinc-100);
  --sidebar-row-hover: var(--color-zinc-25);
  --sidebar-row-active: var(--color-white);
  --sidebar-row-selected: var(--color-white);
  --sidebar-border: var(--border);
  --sidebar-stage-fade: var(--sidebar);
  --code-background: color-mix(in srgb, var(--card) 90%, var(--background));
  --code-foreground: var(--foreground);
  --terminal-background: var(--background);
  --terminal-foreground: var(--foreground);
  --terminal-cursor: rgb(38 56 78);
  --terminal-selection-background: rgb(37 63 99 / 20%);

  @variant dark {
    color-scheme: dark;
    /* The canvas is true black, matching the sidebar. Raised surfaces keep the tone they had
       over neutral-950, so cards, popovers, and the composer still lift. Borders and hover
       states provide separation without milky gray fills. */
    --background: #000;
    --surface-raised: color-mix(in srgb, var(--color-neutral-950) 97%, var(--color-white));
    --foreground: var(--color-neutral-100);
    --card: color-mix(in srgb, var(--color-neutral-950) 97%, var(--color-white));
    --card-foreground: var(--color-neutral-100);
    --popover: color-mix(in srgb, var(--color-neutral-950) 97%, var(--color-white));
    --popover-foreground: var(--color-neutral-100);
    --primary: oklch(0.571 0.21 264);
    --secondary: --alpha(var(--color-white) / 3%);
    --secondary-foreground: var(--color-neutral-100);
    --muted: --alpha(var(--color-white) / 3%);
    --muted-foreground: var(--color-neutral-400);
    --accent: --alpha(var(--color-white) / 4%);
    --accent-foreground: var(--color-neutral-100);
    /* A user turn sits above the composer tone, level with the selected sidebar row. */
    --message-surface: color-mix(in srgb, var(--color-neutral-950) 92%, var(--color-white));
    --error: color-mix(in srgb, var(--color-red-500) 90%, var(--color-white));
    --error-foreground: var(--color-red-400);
    --tool-error-icon: #fca5a5;
    --error-surface: color-mix(in srgb, var(--error) 16%, transparent);
    --border: --alpha(var(--color-white) / 8%);
    --input: --alpha(var(--color-white) / 11%);
    --info-foreground: var(--color-blue-400);
    --guest-foreground: var(--color-fuchsia-300);
    --success-foreground: var(--color-emerald-400);
    --warning-foreground: var(--color-amber-400);
    --warning-surface: color-mix(in srgb, var(--warning) 16%, transparent);
    --update-foreground: var(--color-blue-400);
    --sidebar: var(--card);
    --sidebar-control-surface: var(--muted);
    --sidebar-row-hover: var(--accent);
    --sidebar-row-active: var(--accent);
    --sidebar-row-selected: var(--muted);
    --sidebar-stage-fade: var(--card);
    --terminal-cursor: rgb(180 203 255);
    --terminal-selection-background: rgb(180 203 255 / 25%);
  }
}

/* Keep both sidebar implementations (default and legacy) on the same quiet
   zinc hierarchy: zinc-50 navigation, zinc-25 hover, and white selected/raised
   surfaces. */
[data-app-sidebar] {
  --background: var(--color-zinc-25);
  --foreground: var(--color-zinc-900);
  --card: var(--color-white);
  --card-foreground: var(--color-zinc-900);
  --accent: var(--color-zinc-100);
  --accent-foreground: var(--color-zinc-900);
  --muted: var(--color-zinc-50);
  --muted-foreground: var(--color-zinc-500);
  --border: var(--color-zinc-200);
  --input: var(--color-zinc-300);
  --sidebar: var(--color-zinc-50);
  --sidebar-foreground: var(--color-zinc-900);
  --sidebar-muted-foreground: var(--color-zinc-500);
  --sidebar-control-surface: var(--color-zinc-100);
  --sidebar-row-hover: var(--color-zinc-25);
  --sidebar-row-active: var(--color-white);
  --sidebar-row-selected: var(--color-white);
  --sidebar-border: var(--color-zinc-200);
  --sidebar-stage-fade: var(--sidebar);

  @variant dark {
    --background: #000;
    --foreground: #f1f3f7;
    --card: #000;
    --card-foreground: var(--foreground);
    --accent: #191a1d;
    --accent-foreground: #f7f9ff;
    --muted: #0a0a0a;
    --muted-foreground: #a3a3a3;
    --border: rgb(255 255 255 / 8%);
    --input: rgb(255 255 255 / 18%);
    --sidebar: var(--card);
    --sidebar-foreground: var(--foreground);
    --sidebar-muted-foreground: var(--muted-foreground);
    --sidebar-control-surface: var(--muted);
    --sidebar-row-hover: color-mix(in srgb, var(--contrast-foreground) 8%, transparent);
    --sidebar-row-active: color-mix(in srgb, var(--contrast-foreground) 11%, transparent);
    --sidebar-row-selected: color-mix(in srgb, var(--contrast-foreground) 7%, transparent);
    --sidebar-border: var(--border);
    --sidebar-stage-fade: var(--card);
    /* Row metadata sits a step below read titles (75% white). */
    --secondary-label: #8f8f8f;
  }
}

/* Modified files get a muted blue so added and deleted files lead. Built from the info token,
   which themes do not override, so it stays blue in every theme. */
:root {
  --diff-modified-icon: color-mix(in srgb, var(--info-foreground) 50%, var(--muted-foreground));

  @variant dark {
    /* On black a gray mix stays as bright as the blue, so dim with transparency instead. */
    --diff-modified-icon: color-mix(in srgb, var(--info-foreground) 65%, transparent);
    --diff-added-icon: var(--success-foreground);
  }
}

/* Blue-orange already spends blue on additions. Same specificity as the dark block above and
   later, so it wins there too. */
:root[data-diff-color-scheme="blue-orange"] {
  --diff-modified-icon: var(--muted-foreground);
  --diff-added-icon: initial;

  @variant dark {
    --diff-modified-icon: color-mix(in srgb, var(--muted-foreground) 65%, transparent);
  }
}

/* Sections in the provider detail pane sit flat in its card instead of nesting cards inside
   it. Headings and row dividers still separate them. */
[data-provider-detail] [data-slot="settings-group"] {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

/* A diff header's copy button shows on file hover or focus. */
@media (hover: hover) {
  diffs-container:not(:hover) [data-diff-copy-path]:not(:focus-within) {
    opacity: 0;
  }
}

/* Theme files are expressed in app color roles and mapped to the existing
   semantic surface tokens here. Keep this block after the sidebar-version
   compatibility overrides so both navigation implementations receive the
   same palette. Success, info, provider, and channel identity colors remain
   independent; error, warning, and update roles are themeable below. */
/* The non-empty marker adds enough specificity to outrank the generated root
   dark variant without reintroducing raw `.dark` selectors. */
html[data-theme-id]:not([data-theme-id=""]) {
  --background: var(--app-theme-canvas);
  --app-chrome-background: var(--app-theme-chrome);
  --toolbar-background: var(--app-theme-toolbar);
  --toolbar-foreground: var(--app-theme-toolbar-foreground);
  --toolbar-border: var(--app-theme-toolbar-border);
  --toolbar-control: var(--app-theme-toolbar-control);
  --toolbar-control-foreground: var(--app-theme-toolbar-control-foreground);
  --toolbar-control-hover: var(--app-theme-toolbar-control-hover);
  --surface-raised: var(--app-theme-surface-raised);
  --foreground: var(--app-theme-text);
  --card: var(--app-theme-surface);
  --card-foreground: var(--app-theme-text);
  --popover: var(--app-theme-surface-overlay);
  --popover-foreground: var(--app-theme-text);
  /* Solid controls (CTAs, switches, sliders, the send button) all share the
     theme's action color so every "act now" affordance reads consistently;
     the accent keeps driving surfaces, selection, and focus. Palettes without
     a distinct action color make these identical. */
  --primary: var(--app-theme-message-action);
  --primary-foreground: var(--app-theme-message-action-foreground);
  --secondary: var(--app-theme-secondary);
  --secondary-foreground: var(--app-theme-secondary-foreground);
  --muted: var(--app-theme-muted);
  --muted-foreground: var(--app-theme-muted-foreground);
  --placeholder: var(--app-theme-placeholder);
  --secondary-label: var(--app-theme-secondary-label);
  --icon-muted: var(--app-theme-icon-muted);
  --accent: var(--app-theme-accent-surface);
  --accent-foreground: var(--app-theme-accent-surface-foreground);
  --message-surface: var(--app-theme-message-surface);
  --message-foreground: var(--app-theme-message-foreground);
  --message-action: var(--app-theme-message-action);
  --message-action-foreground: var(--app-theme-message-action-foreground);
  --message-action-hover: var(--app-theme-message-action-hover);
  --error: var(--app-theme-error);
  --error-foreground: var(--app-theme-error-foreground);
  --tool-error-icon: var(--error-foreground);
  --error-surface: var(--app-theme-error-surface);
  --destructive: var(--error);
  --destructive-foreground: var(--error-foreground);
  --warning: var(--app-theme-warning);
  --warning-foreground: var(--app-theme-warning-foreground);
  --warning-surface: var(--app-theme-warning-surface);
  --update: var(--app-theme-update);
  --update-foreground: var(--app-theme-update-foreground);
  --border: var(--app-theme-border);
  --input: var(--app-theme-input);
  --ring: var(--app-theme-focus);
  --sidebar: var(--app-theme-sidebar);
  --sidebar-foreground: var(--app-theme-sidebar-foreground);
  --sidebar-muted-foreground: var(--app-theme-sidebar-muted-foreground);
  --sidebar-control-surface: var(--app-theme-sidebar-control-surface);
  --sidebar-row-hover: var(--app-theme-sidebar-row-hover);
  --sidebar-row-active: var(--app-theme-sidebar-row-active);
  --sidebar-row-selected: var(--app-theme-sidebar-row-selected);
  --sidebar-border: var(--app-theme-sidebar-border);
  --sidebar-stage-fade: var(--app-theme-sidebar);
  --code-background: var(--app-theme-code-background);
  --code-foreground: var(--app-theme-code-foreground);
  --terminal-background: var(--app-theme-terminal-background);
  --terminal-foreground: var(--app-theme-terminal-foreground);
  --terminal-cursor: var(--app-theme-terminal-cursor);
  --terminal-selection-background: var(--app-theme-terminal-selection-background);
}

/* Theme-token dependency probes are restored synchronously, before paint. Keep
   transitions from observing the temporary sentinel color in between. */
html[data-theme-token-probe],
html[data-theme-token-probe] *,
html[data-theme-token-probe] *::before,
html[data-theme-token-probe] *::after {
  transition: none !important;
}

#theme-inspector-spotlight {
  position: fixed;
  z-index: 100;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  overflow: visible;
  pointer-events: none;
}

[data-slot="popover-positioner"]:has([data-theme-editor-panel]),
[data-slot="tooltip-positioner"]:has([data-theme-editor-panel]) {
  z-index: 120;
}

.theme-inspector-spotlight-dimmer {
  fill: rgb(2 3 8 / 54%);
}

.theme-inspector-spotlight-glow {
  fill: color-mix(in oklab, var(--ring) 9%, transparent);
  stroke: color-mix(in oklab, var(--ring) 72%, white);
  stroke-width: 2px;
  opacity: 0.92;
  vector-effect: non-scaling-stroke;
}

#theme-inspector-hover {
  position: fixed;
  z-index: 101;
  pointer-events: none;
  background: color-mix(in oklab, var(--ring) 7%, transparent);
  border: 1px solid color-mix(in oklab, var(--ring) 70%, white);
  box-shadow:
    0 0 0 3px color-mix(in oklab, var(--ring) 16%, transparent),
    0 0 18px color-mix(in oklab, var(--ring) 38%, transparent);
}

#theme-inspector-hover [data-theme-inspector-hover-label] {
  position: absolute;
  left: 0;
  max-width: 12rem;
  overflow: hidden;
  padding: 0.2rem 0.45rem;
  border: 1px solid color-mix(in oklab, var(--ring) 48%, var(--contrast-border));
  border-radius: 0.4rem;
  background: var(--popover);
  box-shadow: 0 4px 16px rgb(0 0 0 / 24%);
  color: var(--contrast-popover-foreground);
  font-size: 0.6875rem;
  font-weight: 600;
  line-height: 1rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

#theme-inspector-hover[data-placement="above"] [data-theme-inspector-hover-label] {
  bottom: calc(100% + 0.35rem);
}

#theme-inspector-hover[data-placement="below"] [data-theme-inspector-hover-label] {
  top: calc(100% + 0.35rem);
}

/* Workspace actions use a small, separate chrome hierarchy. Keeping these
   roles explicit prevents the thread toolbar from falling back to the default
   dark-mode whites while preserving the same theme file across clients. */
html[data-theme-id] [data-chat-header] {
  background-color: var(--toolbar-background);
  color: var(--contrast-toolbar-foreground);
}

html[data-theme-id] [data-chat-header] [data-slot="button"],
html[data-theme-id] [data-chat-header] [data-slot="menu-trigger"],
html[data-theme-id] [data-chat-header] [data-toolbar-control] {
  --control-icon-color: var(--contrast-toolbar-control-foreground);
  background-color: var(--toolbar-control);
  border-color: var(--contrast-toolbar-border);
  color: var(--contrast-toolbar-control-foreground);
}

/* The panel layout toggles stay ghost: they render both inside the header and
   in the titlebar strip, so filling them would make them change appearance as
   the panel opens. They only take the themed foreground; hover and pressed
   keep the base ghost accent. The tooltip trigger's data-slot wins over the
   toggle's when the trigger renders the toggle, so match both. */
html[data-theme-id] [data-panel-layout-controls] [data-slot="toggle"],
html[data-theme-id] [data-panel-layout-controls] [data-slot="tooltip-trigger"],
html[data-theme-id] [data-workspace-titlebar-controls] [data-slot="toggle"],
html[data-theme-id] [data-workspace-titlebar-controls] [data-slot="tooltip-trigger"] {
  --control-icon-color: var(--contrast-toolbar-foreground);
  color: var(--contrast-toolbar-foreground);
}

html[data-theme-id] [data-panel-layout-controls] [data-slot="toggle"]:disabled,
html[data-theme-id] [data-panel-layout-controls] [data-slot="tooltip-trigger"]:disabled,
html[data-theme-id] [data-workspace-titlebar-controls] [data-slot="toggle"]:disabled,
html[data-theme-id] [data-workspace-titlebar-controls] [data-slot="tooltip-trigger"]:disabled {
  --control-icon-color: color-mix(
    in oklab,
    var(--contrast-toolbar-foreground) 55%,
    var(--toolbar-background)
  );
  color: color-mix(in oklab, var(--contrast-toolbar-foreground) 55%, var(--toolbar-background));
}

html[data-theme-id] [data-chat-header] [data-slot="button"]:hover,
html[data-theme-id] [data-chat-header] [data-slot="button"][data-pressed],
html[data-theme-id] [data-chat-header] [data-slot="menu-trigger"]:hover,
html[data-theme-id] [data-chat-header] [data-slot="menu-trigger"][data-pressed],
html[data-theme-id] [data-chat-header] [data-toolbar-control]:hover,
html[data-theme-id] [data-chat-header] [data-toolbar-control][data-pressed] {
  background-color: var(--toolbar-control-hover);
}

html[data-theme-id] [data-chat-header] [data-slot="separator"] {
  background-color: var(--contrast-toolbar-border);
}

/* Chat code blocks join the other code surfaces on the code tokens. The
   default look keeps its secondary/input tints; themed palettes tint those
   surfaces with the accent, which fights syntax highlighting. */
html[data-theme-id] :is(.chat-markdown, .composer-tiptap) .chat-markdown-codeblock {
  background-color: var(--code-background);
  border-color: var(--contrast-border);
  color: var(--code-foreground);
}

html[data-theme-id] .chat-markdown pre {
  background-color: var(--code-background);
  color: var(--code-foreground);
}

html[data-theme-id] :is(.chat-markdown, .composer-tiptap) .chat-markdown-codeblock pre {
  background-color: transparent;
}

html[data-theme-id] :is(.chat-markdown, .composer-tiptap) .chat-markdown-codeblock-header {
  color: color-mix(in srgb, var(--code-foreground) 72%, transparent);
}

/* T3 Chat renders inline code and compact chat artifacts with its translucent
   secondary surface flattened over the light chat canvas. The raw muted and
   secondary tokens are substantially darker than those visible pixels. */
html[data-theme-id="t3-chat"] {
  @variant light {
    & .chat-markdown :not(pre) > code,
    & [data-changed-files-state],
    & [data-changed-files-header] {
      background-color: var(--message-surface);
    }

    & .chat-markdown :not(pre) > code,
    & [data-changed-files-state] {
      border-color: transparent;
    }

    & .chat-markdown :not(pre) > code {
      color: var(--contrast-message-foreground);
    }
  }
}

html[data-theme-id] [data-app-sidebar] {
  --background: var(--app-theme-canvas);
  --foreground: var(--app-theme-text);
  --card: var(--app-theme-surface);
  --card-foreground: var(--app-theme-text);
  --accent: var(--app-theme-accent-surface);
  --accent-foreground: var(--app-theme-accent-surface-foreground);
  --muted: var(--app-theme-muted);
  --muted-foreground: var(--app-theme-muted-foreground);
  --border: var(--app-theme-border);
  --input: var(--app-theme-input);
  --sidebar: var(--app-theme-sidebar);
  --sidebar-foreground: var(--app-theme-sidebar-foreground);
  --sidebar-muted-foreground: var(--app-theme-sidebar-muted-foreground);
  --sidebar-control-surface: var(--app-theme-sidebar-control-surface);
  --sidebar-row-hover: var(--app-theme-sidebar-row-hover);
  --sidebar-row-active: var(--app-theme-sidebar-row-active);
  --sidebar-row-selected: var(--app-theme-sidebar-row-selected);
  --sidebar-border: var(--app-theme-sidebar-border);
  --sidebar-stage-fade: var(--app-theme-sidebar);
  border-color: color-mix(in srgb, var(--contrast-sidebar-foreground) 10%, transparent);

  @variant dark {
    border-color: color-mix(in srgb, var(--contrast-sidebar-foreground) 8%, transparent);
  }
}

/* T3 Chat's panel divider is deliberately pink, and its resize affordance
   keeps that color while hovered. Do not neutralize this branded edge. */
html[data-theme-id="t3-chat"] [data-app-sidebar] {
  @variant dark {
    border-color: var(--contrast-sidebar-border);
  }
}

/* Recompute contrast wherever a subtree owns its own semantic color palette. */
:root,
[data-app-sidebar] {
  --contrast-toolbar-foreground: color-mix(
    in oklab,
    color-mix(
      in oklab,
      var(--toolbar-foreground) var(--appearance-contrast-base),
      var(--toolbar-background)
    ),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-toolbar-border: color-mix(
    in srgb,
    color-mix(in srgb, var(--toolbar-border) var(--appearance-contrast-base), transparent),
    var(--toolbar-foreground) var(--appearance-contrast-border-boost)
  );
  --contrast-toolbar-control-foreground: color-mix(
    in oklab,
    color-mix(
      in oklab,
      var(--toolbar-control-foreground) var(--appearance-contrast-base),
      var(--toolbar-control)
    ),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-input: color-mix(
    in srgb,
    color-mix(in srgb, var(--input) var(--appearance-contrast-base), transparent),
    var(--foreground) var(--appearance-contrast-border-boost)
  );
  --contrast-border: color-mix(
    in srgb,
    color-mix(in srgb, var(--border) var(--appearance-contrast-base), transparent),
    var(--foreground) var(--appearance-contrast-border-boost)
  );
  --contrast-foreground: color-mix(
    in oklab,
    color-mix(in oklab, var(--foreground) var(--appearance-contrast-base), var(--background)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-muted-foreground: color-mix(
    in oklab,
    color-mix(in oklab, var(--muted-foreground) var(--appearance-contrast-base), var(--background)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-placeholder: color-mix(
    in oklab,
    color-mix(in oklab, var(--placeholder) var(--appearance-contrast-base), var(--background)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-secondary-label: color-mix(
    in oklab,
    color-mix(in oklab, var(--secondary-label) var(--appearance-contrast-base), var(--background)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-icon-muted: color-mix(
    in oklab,
    color-mix(in oklab, var(--icon-muted) var(--appearance-contrast-base), var(--background)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-card-foreground: color-mix(
    in oklab,
    color-mix(in oklab, var(--card-foreground) var(--appearance-contrast-base), var(--card)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-popover-foreground: color-mix(
    in oklab,
    color-mix(in oklab, var(--popover-foreground) var(--appearance-contrast-base), var(--popover)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-accent-foreground: color-mix(
    in oklab,
    color-mix(in oklab, var(--accent-foreground) var(--appearance-contrast-base), var(--accent)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-secondary-foreground: color-mix(
    in oklab,
    color-mix(
      in oklab,
      var(--secondary-foreground) var(--appearance-contrast-base),
      var(--secondary)
    ),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-message-foreground: color-mix(
    in oklab,
    color-mix(
      in oklab,
      var(--message-foreground) var(--appearance-contrast-base),
      var(--message-surface)
    ),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-sidebar-foreground: color-mix(
    in oklab,
    color-mix(in oklab, var(--sidebar-foreground) var(--appearance-contrast-base), var(--sidebar)),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-sidebar-muted-foreground: color-mix(
    in oklab,
    color-mix(
      in oklab,
      var(--sidebar-muted-foreground) var(--appearance-contrast-base),
      var(--sidebar)
    ),
    var(--appearance-contrast-target) var(--appearance-contrast-boost)
  );
  --contrast-sidebar-border: color-mix(
    in srgb,
    color-mix(in srgb, var(--sidebar-border) var(--appearance-contrast-base), transparent),
    var(--sidebar-foreground) var(--appearance-contrast-border-boost)
  );
}

body {
  /* Reference the theme token (not a literal stack) so the Settings ->
     Appearance runtime override of --font-sans reaches all interface text. */
  font-family: var(--font-sans);
  margin: 0;
  padding: 0;
}

/* Lighter default icon stroke. In the base layer so stroke-* utilities still win; any
   CSS beats lucide's stroke-width="2" attribute. */
@layer base {
  :where(svg.lucide[stroke-width="2"]) {
    stroke-width: 1.75;
  }
}

html,
body {
  min-height: calc(100svh + env(safe-area-inset-top));
  overscroll-behavior: none;
}

body {
  height: 100%;
  overflow: hidden;
}

#root {
  height: 100%;
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
  overflow-x: clip;
  overflow-y: hidden;
  overscroll-behavior-y: none;
  padding-top: max(env(safe-area-inset-top), 0px);
  padding-right: var(--desktop-window-right-resize-inset);
}

.electron-windows {
  --desktop-window-right-resize-inset: 6px;
}

/* App-chrome grain. Baked into each surface's own background (behind
   content) rather than a fixed overlay on top: a full-viewport overlay
   forces the compositor to re-blend every frame any animation produces,
   which multiplied idle GPU cost. The overlay's 0.035 opacity lives in the
   SVG rect instead. Surfaces that float over the body (e.g. the inset main
   card) must opt in via the surface-grain utility, or they lose the
   grain's subtle brightening and stand out against the body. */
:root {
  --surface-grain: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.035'/%3E%3C/svg%3E");
  --surface-grain-size: 256px 256px;
}

/* The live T3 Chat texture is a 128px grayscale tile with a constant 7/255
   alpha. Keep our procedural texture cheap while matching that scale and
   strength for the branded preset. */
html[data-theme-id="t3-chat"] {
  --surface-grain: url("data:image/svg+xml,%3Csvg viewBox='0 0 128 128' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.02745'/%3E%3C/svg%3E");
  --surface-grain-size: 128px 128px;
}

body {
  background-image: var(--surface-grain);
  background-repeat: repeat;
  background-size: var(--surface-grain-size);
}

pre,
code {
  font-family: var(--font-mono);
}

/* Code blocks in chat carry the size preference. Scoped to chat markdown
   rather than every pre: a global rule would beat text-size utilities and
   inherited sizes on unrelated pre surfaces (terminal previews, approvals).
   Inline code stays relative to its sentence so it never towers over prose;
   diffs and file previews take the size through --diffs-font-size. */
.chat-markdown .chat-markdown-shiki :is(.shiki, .diffs),
.chat-markdown .chat-markdown-codeblock pre,
:is(.chat-markdown, .composer-tiptap) pre code {
  font-size: var(--font-size-code, inherit);
}

/* @pierre/diffs surfaces (diffs, file previews, annotatable code, search
   lines) render inside shadow roots but consult these hooks with their own
   literal stacks as fallback. Custom properties inherit across the shadow
   boundary, so defining them once here routes every code surface through the
   appearance font tokens. */
:root {
  --diffs-font-family: var(--font-mono);
  --diffs-header-font-family: var(--font-sans);
}

/* Pele diagrams read their colors through these, so a theme change recolors
   them without re-rendering. */
.pele {
  --pele-bg: var(--background);
  --pele-fg: var(--foreground);
  --pele-muted: var(--muted-foreground);
  --pele-line: var(--muted-foreground);
  --pele-surface: var(--secondary);
  --pele-surface-alt: var(--accent);
  --pele-border: color-mix(in srgb, var(--foreground) 28%, transparent);
  --pele-accent: var(--primary);
  --pele-critical: var(--destructive);
}

/* Window drag region (frameless titlebar) */
.drag-region {
  -webkit-app-region: drag;
}

/* Electron 44 inherits app-region. Reset children to the initial value so they
   do not add drag rectangles over fixed controls. Explicit `none` is treated
   as `no-drag` and breaks titlebar dragging; `initial` emits no rectangle.
   The base layer lets explicit drag/no-drag utilities take precedence. */
@layer base {
  .drag-region > * {
    -webkit-app-region: initial;
  }
}

.drag-region button,
.drag-region input,
.drag-region textarea,
.drag-region select,
.drag-region a {
  -webkit-app-region: no-drag;
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: var(--app-scrollbar-width);
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: var(--app-scrollbar-thumb);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--app-scrollbar-thumb-hover);
}

/* Chat markdown rendering */

.chat-markdown > :first-child {
  margin-top: 0;
}

.chat-markdown > :last-child {
  margin-bottom: 0;
}

.chat-markdown p,
.chat-markdown ul,
.chat-markdown ol,
.chat-markdown blockquote,
.chat-markdown pre,
.chat-markdown .chat-markdown-table-container,
.composer-tiptap ul,
.composer-tiptap ol {
  margin: 0.65rem 0;
}

.chat-markdown-math-display .katex-display {
  margin: 0;
}

:is(.chat-markdown, .composer-tiptap) h1,
:is(.chat-markdown, .composer-tiptap) h2,
:is(.chat-markdown, .composer-tiptap) h3,
:is(.chat-markdown, .composer-tiptap) h4,
:is(.chat-markdown, .composer-tiptap) h5,
:is(.chat-markdown, .composer-tiptap) h6 {
  margin: 1.25rem 0 0.5rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--contrast-foreground);
}

:is(.chat-markdown, .composer-tiptap) h1 {
  font-size: 1.25rem;
}

:is(.chat-markdown, .composer-tiptap) h2 {
  font-size: 1.125rem;
}

:is(.chat-markdown, .composer-tiptap) h3 {
  font-size: 1rem;
}

:is(.chat-markdown, .composer-tiptap) h4,
:is(.chat-markdown, .composer-tiptap) h5,
:is(.chat-markdown, .composer-tiptap) h6 {
  font-size: 0.875rem;
}

:is(.chat-markdown, .composer-tiptap) h6 {
  color: var(--contrast-muted-foreground);
}

:is(.chat-markdown, .composer-tiptap) ul {
  /* Reset for nested uls under a widened ol. --list-gutter is an inherited
     custom property, so without this a task-list under a multi-digit ordered
     list would inherit the outer gutter instead of its own default. */
  --list-gutter: 1.25rem;
  padding-inline-start: 1.25rem;
  list-style-type: disc;
}

/* --list-gutter defaults to the same 1.25rem as .chat-markdown ul, but
   ChatMarkdown's `ol` renderer widens it (via inline style) for lists whose
   widest marker has multiple characters so it isn't clipped by list-style-position:
   outside painting the marker past the padding box. Reset it here too so a
   nested ol without its own widened marker doesn't inherit the outer one. */
:is(.chat-markdown, .composer-tiptap) ol {
  --list-gutter: 1.25rem;
  padding-inline-start: var(--list-gutter, 1.25rem);
  list-style-type: decimal;
}

:is(.chat-markdown, .composer-tiptap) ol > li::marker {
  font-variant-numeric: tabular-nums;
}

/* The composer shows the marker the source has, `3)` or a nested `7.`, not the
   browser counter. Browsers without ::marker content fall back to `start`. */
.composer-tiptap ol > li[data-marker]::marker {
  content: attr(data-marker) " ";
}

/* The prompt font and size can differ from the interface, so its gutter must
   also follow the prompt's font metrics. */
.composer-tiptap ol {
  --list-gutter: max(1.25rem, 3ch);
}

.composer-tiptap ol:has(> li[data-marker-width="3"]) {
  --list-gutter: max(1.25rem, 4ch);
}

.composer-tiptap ol:has(> li[data-marker-width="4"]) {
  --list-gutter: max(1.25rem, 5ch);
}

.composer-tiptap ol:has(> li[data-marker-width="5"]) {
  --list-gutter: max(1.25rem, 6ch);
}

.composer-tiptap ol:has(> li[data-marker-width="6"]) {
  --list-gutter: max(1.25rem, 7ch);
}

.composer-tiptap ol:has(> li[data-marker-width="7"]) {
  --list-gutter: max(1.25rem, 8ch);
}

.composer-tiptap ol:has(> li[data-marker-width="8"]) {
  --list-gutter: max(1.25rem, 9ch);
}

.composer-tiptap ol:has(> li[data-marker-width="9"]) {
  --list-gutter: max(1.25rem, 10ch);
}

.composer-tiptap ol:has(> li[data-marker-width="10"]) {
  --list-gutter: max(1.25rem, 11ch);
}

.composer-tiptap ul {
  padding-inline-start: max(1.25rem, 2ch);
}

:is(.chat-markdown, .composer-tiptap) ul ul {
  list-style-type: circle;
}

:is(.chat-markdown, .composer-tiptap) ul ul ul {
  list-style-type: square;
}

.chat-markdown ol ol {
  list-style-type: lower-alpha;
}

.chat-markdown ol ol ol {
  list-style-type: lower-roman;
}

.chat-markdown li + li {
  margin-top: 0.25rem;
}

/* GitHub-style task lists: the checkbox replaces the list marker. */
.chat-markdown li.task-list-item {
  list-style-type: none;
}

.chat-markdown li.task-list-item input[type="checkbox"] {
  margin-block: 0 0.15em;
  margin-inline: calc(-1 * var(--list-gutter, 1.25rem)) 0.35em;
  vertical-align: middle;
}

/* Markdown assumes inline images — GitHub comments lay button images out in a row — and the
   Tailwind preflight's block-level img would stack them one per line. */
.chat-markdown img {
  display: inline-block;
}

.chat-markdown a {
  text-decoration: none;
}

/* File links and context chips own their color and focus ring. */
.chat-markdown a:not(.chat-markdown-file-link, :has([data-slot="context-chip-label"])) {
  color: var(--info-foreground);
}

.chat-markdown
  a:not(
    .chat-markdown-file-link,
    :has([data-slot="context-chip-label"]),
    [data-markdown-image-link]
  ):hover,
.chat-markdown
  a:not(
    .chat-markdown-file-link,
    :has([data-slot="context-chip-label"]),
    [data-markdown-image-link]
  ):focus-visible {
  background-image: radial-gradient(circle, currentcolor 0.75px, transparent 1px);
  background-position: left bottom;
  background-repeat: repeat-x;
  background-size: 4px 2px;
}

:is(.chat-markdown, .composer-tiptap) blockquote {
  border-inline-start: 2px solid color-mix(in srgb, currentcolor 35%, transparent);
  padding-inline-start: 0.8rem;
  color: inherit;
}

.composer-tiptap blockquote {
  margin: 0.65rem 0;
}

/* Preflight already draws the 1px rule, as it does in chat; only the block
   spacing needs to match. */
.composer-tiptap hr {
  margin: 0.65rem 0;
}

/* Block spacing separates blocks, not the draft from the composer edge. A
   leading list or quote would otherwise push the first line down, and the
   one-line resting composer clips it. */
.composer-tiptap > :first-child {
  margin-top: 0;
}

.composer-tiptap > :last-child {
  margin-bottom: 0;
}

/* A heading at the top of a draft should not push the first line down. */
.composer-tiptap :is(h1, h2, h3, h4, h5, h6):first-child {
  margin-top: 0;
}

.chat-markdown section[data-footnotes] {
  margin-top: 1.25rem;
  border-top: 1px solid var(--contrast-border);
  padding-top: 0.75rem;
  color: var(--contrast-muted-foreground);
  font-size: 0.75rem;
}

.chat-markdown section[data-footnotes] ol {
  margin: 0;
}

.chat-markdown section[data-footnotes] li + li {
  margin-top: 0.35rem;
}

.chat-markdown a[data-footnote-ref],
.chat-markdown a[data-footnote-backref] {
  display: inline-flex;
  min-width: 1rem;
  align-items: center;
  justify-content: center;
  border-radius: 0.25rem;
  text-decoration: none;
  font-size: 0.6875rem;
  font-weight: 600;
}

.chat-markdown :not(pre) > code {
  border: 1px solid transparent;
  border-radius: 0.25rem;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
  background: color-mix(in srgb, var(--contrast-foreground) 10%, transparent);
  padding: 0.1em 0.35em;
  color: var(--contrast-foreground);
  font-size: 0.85em;
}

.chat-markdown strong {
  font-weight: 600;
}

.chat-markdown pre {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid var(--contrast-border);
  border-radius: 0.5rem;
  background: var(--muted);
  padding: 0.8rem 0.9rem;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--contrast-border) 78%, transparent) transparent;
}

.chat-markdown pre code {
  border: none;
  background: transparent;
  padding: 0;
}

.chat-markdown pre::-webkit-scrollbar {
  height: var(--app-scrollbar-width);
}

.chat-markdown pre::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: color-mix(in srgb, var(--contrast-border) 78%, transparent);
}

:is(.chat-markdown, .composer-tiptap) .chat-markdown-codeblock-header {
  color: color-mix(in srgb, var(--contrast-foreground) 72%, transparent);
}

:is(.chat-markdown, .composer-tiptap) .chat-markdown-codeblock pre {
  margin: 0;
  border: none;
  border-radius: 0;
  background: transparent;
}

:is(.chat-markdown, .composer-tiptap) .chat-markdown-codeblock[data-wrap="true"] pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

:is(.chat-markdown, .composer-tiptap) .chat-markdown-shiki :is(.shiki, .diffs) {
  background: transparent !important;
}

/* Paragraphs and code blocks arrive in chunks while a response streams. Fade
   each new block in so the chunk does not pop. @starting-style only applies
   when an element is first inserted, and the rule is gated on data-streaming,
   so opening a finished thread never replays the fade. Opacity only, one
   shot, no layout change. */
@media (prefers-reduced-motion: no-preference) {
  .chat-markdown[data-streaming] > *,
  .chat-markdown[data-streaming] .chat-markdown-shiki,
  .chat-markdown[data-streaming] .chat-markdown-mermaid {
    transition: opacity 600ms ease-out;

    @starting-style {
      opacity: 0;
    }
  }
}

/* Diagnostics-style tables: row separators only, and a scroll-fade container
   for horizontal overflow. Cells wrap and the table fits its lane. The root
   chat-markdown wrapping rules (overflow-wrap: anywhere) would let columns
   shrink to single characters, so restore word-boundary wrapping: the min
   column width is the longest word, and only wider content scrolls. */
.chat-markdown table {
  width: 100%;
  border-collapse: collapse;
  overflow-wrap: normal;
  word-break: normal;
  /* One step under 15px prose. */
  font-size: 0.875rem;
}

/* Top-aligned so wrapped rows share a first line, and the outer columns sit
   flush with the surrounding prose. */
.chat-markdown th,
.chat-markdown td {
  padding: 0.45rem 0.75rem;
  text-wrap: pretty;
  text-align: start;
  vertical-align: top;
}

.chat-markdown :is(th, td):first-child {
  padding-inline-start: 0;
}

.chat-markdown :is(th, td):last-child {
  padding-inline-end: 0;
}

.chat-markdown thead th {
  border-bottom: 1px solid color-mix(in srgb, var(--contrast-border) 60%, transparent);
  padding-block: 0.55rem;
  font-weight: 600;
}

.chat-markdown tbody td {
  border-bottom: 1px solid color-mix(in srgb, var(--contrast-border) 60%, transparent);
}

/* Caps a long path, URL, or chip at 24rem; text past the cap wraps. */
.chat-markdown :is(th, td) {
  max-width: 24rem;
  overflow-wrap: break-word;
}

/* Formula cells keep their natural width and scroll with the table. */
.chat-markdown :is(th, td):has([data-markdown-math]) {
  max-width: none;
}

:root {
  --diff-addition: var(--success);
  --diff-deletion: var(--destructive);
  --diff-addition-foreground: light-dark(var(--color-emerald-700), var(--color-emerald-400));
  --diff-deletion-foreground: light-dark(var(--color-red-700), var(--color-red-400));
}

/* Chat width setting. Comfortable keeps the default --chat-content-max-width,
   which sizes the timeline lane, the composer, and ChatCanvas's width probe. */
:root[data-chat-width="wide"] {
  --chat-content-max-width: 72rem;
}

:root[data-chat-width="full"] {
  --chat-content-max-width: 100%;
}

:root[data-diff-color-scheme="blue-orange"] {
  --diff-addition: light-dark(var(--color-blue-600), var(--color-blue-400));
  --diff-deletion: light-dark(var(--color-orange-600), var(--color-orange-400));
  --diff-addition-foreground: var(--diff-addition);
  --diff-deletion-foreground: var(--diff-deletion);
  --diffs-addition-color-override: var(--diff-addition);
  --diffs-deletion-color-override: var(--diff-deletion);
  --trees-status-added-override: var(--diff-addition);
  --trees-status-deleted-override: var(--diff-deletion);
  --trees-status-untracked-override: var(--diff-addition);
  --trees-git-added-color-override: var(--diff-addition);
  --trees-git-deleted-color-override: var(--diff-deletion);
  --trees-git-untracked-color-override: var(--diff-addition);
}

.diff-render-surface diffs-container {
  border: 0;
  border-radius: 0;
  overflow: clip;
  background: var(--code-background);
  color: var(--code-foreground);
}

/* Pierre's find panel and match highlights read these. */
.diff-render-surface {
  --diffs-search-panel-bg: var(--popover);
  --diffs-search-panel-fg: var(--popover-foreground);
  --diffs-search-panel-accent: var(--primary);
  --diffs-search-panel-font: var(--font-sans);
}

/* Pierre's file renderer owns its own surface tokens. Keep the root of a file
   preview on the same themeable code surface as the diff panel. */
.diff-render-surface diffs-container,
.file-preview-virtualizer diffs-container {
  --diffs-bg: var(--code-background) !important;
  --diffs-light-bg: var(--code-background) !important;
  --diffs-dark-bg: var(--code-background) !important;
  background-color: var(--code-background) !important;
  color: var(--code-foreground) !important;
}

.ultrathink-frame {
  --ultrathink-spectrum: linear-gradient(
    120deg,
    #ff6b6b 0%,
    #f59e0b 18%,
    #22c55e 36%,
    #14b8a6 54%,
    #3b82f6 72%,
    #ec4899 90%,
    #ff6b6b 100%
  );
}

.xhigh-frame {
  --xhigh-spectrum: linear-gradient(120deg, #22d3ee 0%, #34d399 45%, #10b981 70%, #22d3ee 100%);
}

.ultrathink-frame,
.xhigh-frame {
  position: relative;
}

.ultrathink-frame::before,
.xhigh-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 2px;
  background-size: 220% 220%;
  background-position: 0% 50%;
  pointer-events: none;
  filter: saturate(0.82) brightness(0.92);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
}

.ultrathink-frame::before {
  background-image: var(--ultrathink-spectrum);
}

.xhigh-frame::before {
  background-image: var(--xhigh-spectrum);
}

.ultrathink-frame > *,
.xhigh-frame > * {
  position: relative;
}

.ultrathink-chroma,
.xhigh-chroma {
  filter: saturate(1.2);
}

@keyframes preview-loading-progress {
  from {
    transform: scaleX(0.04);
  }

  to {
    transform: scaleX(0.9);
  }
}

.preview-loading-progress {
  opacity: 0;
  transform: scaleX(1);
  transition:
    transform 150ms ease-out,
    opacity 150ms ease-out 220ms;
}

.preview-loading-progress[data-loading="true"] {
  opacity: 1;
  animation: preview-loading-progress 5.3s cubic-bezier(0.1, 0.5, 0.2, 1) forwards;
}

@media (prefers-reduced-motion: reduce) {
  .preview-loading-progress,
  .preview-loading-progress[data-loading="true"] {
    transition: none;
    animation: none;
  }

  .preview-loading-progress[data-loading="true"] {
    transform: scaleX(0.9);
  }
}

/* Let the sortable rows open label clearance before painting the dividers.
   This runs once per pickup; rows retain dnd-kit's normal 200ms transitions. */
.sidebar-drag-boundary-label {
  animation: sidebar-drag-label-reveal 200ms step-end;
}

@keyframes sidebar-drag-label-reveal {
  from {
    visibility: hidden;
  }
  to {
    visibility: visible;
  }
}

/* Rich text composer (Tiptap). The stored prompt stays markdown; only the
   surface renders styled text. Markers (** * ` ~~) appear as non-editable
   widgets while the caret is on styled text. */
.composer-tiptap {
  position: relative;
}

.composer-tiptap p {
  margin: 0;
}

.composer-tiptap:focus,
.composer-tiptap .ProseMirror:focus {
  outline: none;
}

.composer-tiptap :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.92em;
  background: color-mix(in oklab, var(--muted-foreground) 12%, transparent);
  border-radius: 0.3em;
  padding: 0.05em 0.25em;
}

.composer-rich-marker {
  color: var(--muted-foreground);
  opacity: 0.75;
  font-weight: 400;
  font-style: normal;
  text-decoration: none;
  user-select: none;
  pointer-events: none;
}

/* Selected chips (node selection from arrowing into or clicking a chip). */
.composer-tiptap .ProseMirror-selectednode {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
  border-radius: 6px;
}

.composer-tiptap .composer-chip-range-selected {
  position: relative;
}

.composer-tiptap.ProseMirror-focused .composer-chip-range-selected::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 6px;
  background: Highlight;
  opacity: 0.3;
  pointer-events: none;
}

/* Rich-text task lists render as real checkboxes. Tiptap's TaskItem NodeView
   builds the <li> imperatively with only a data-checked attribute (no
   data-type), so items are targeted that way. Indentation comes from list
   nesting (two spaces per level from Tab), matching the stored Markdown. */
.composer-tiptap ul[data-type="taskList"] {
  list-style: none;
  margin: 0;
  padding: 0;
}

.composer-tiptap ul[data-type="taskList"] ul[data-type="taskList"] {
  padding-inline-start: 1.375rem;
}

.composer-tiptap li[data-checked] {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
}

.composer-tiptap li[data-checked] > label {
  display: flex;
  align-items: center;
  flex: none;
  height: 1lh;
  cursor: pointer;
}

.composer-tiptap li[data-checked] > label input[type="checkbox"] {
  display: block;
  margin: 0;
  width: 0.95rem;
  height: 0.95rem;
  cursor: pointer;
}

.composer-tiptap li[data-checked] > div {
  flex: 1 1 auto;
  min-width: 0;
}

.composer-tiptap li[data-checked] > div > p {
  margin: 0;
}

@layer components {
  .chat-composer-lane {
    padding-inline-start: calc(
      env(safe-area-inset-left) + 0.75rem + var(--chat-lane-inset-start, 0px)
    );
    padding-inline-end: calc(
      env(safe-area-inset-right) + 0.75rem + var(--chat-lane-inset-end, 0px)
    );
  }
  [data-chat-canvas] .messages-timeline-scroll {
    padding-inline-start: calc(
      0.75rem + var(--chat-lane-inset-start, 0px) - var(--chat-timeline-gutter, 0px)
    );
    padding-inline-end: calc(
      0.75rem + var(--chat-lane-inset-end, 0px) - var(--chat-timeline-gutter, 0px)
    );
  }
  .chat-scroll-to-bottom,
  .chat-banner-lane {
    inset-inline-start: var(--chat-lane-inset-start, 0px);
    inset-inline-end: var(--chat-lane-inset-end, 0px);
  }
  @media (min-width: 640px) {
    .chat-composer-lane {
      padding-inline-start: calc(
        env(safe-area-inset-left) + 3rem + var(--chat-lane-inset-start, 0px)
      );
      padding-inline-end: calc(env(safe-area-inset-right) + 3rem + var(--chat-lane-inset-end, 0px));
    }
    [data-chat-canvas] .messages-timeline-scroll {
      padding-inline-start: calc(
        3rem + var(--chat-lane-inset-start, 0px) - var(--chat-timeline-gutter, 0px)
      );
      padding-inline-end: calc(
        3rem + var(--chat-lane-inset-end, 0px) - var(--chat-timeline-gutter, 0px)
      );
    }
  }
}

/* A workspace area with no control of its own takes F6 focus itself; keep that visible. */
[data-workspace-area]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

