        yield* updateThread({
          status: "active",
          firstRunOrdinal: providerThread.firstRunOrdinal ?? turnInput.runOrdinal,
          lastRunOrdinal: turnInput.runOrdinal,
          nativeMetadata: {
            ...providerThread.nativeMetadata,
            modelSelection: turnInput.modelSelection,
          },
        });
        if (turnInput.modelSelection.model === "auto")
          yield* refreshSelection(turnInput.modelSelection, turn);
        const userText = yield* providerMessageTextWithAttachmentPaths({
          text: turnInput.message.text,
          attachments: turnInput.message.attachments,
          resolveAttachmentPath: host.resolveAttachmentPath,
        });
        const instructions = buildRuntimeInstructions({
          harness: "GitHub Copilot",
          model: turnInput.modelSelection.model,
          reasoningEffort: effort,
        });
        const context = turnInput.appContext?.map((entry) => entry.text).join("\n\n") ?? "";
        const prompt = [instructions, history, context, userText].filter(Boolean).join("\n\n");
        const attachments: NonNullable<MessageOptions["attachments"]> = [];
        for (const attachment of turnInput.message.attachments) {
          const path = host.resolveAttachmentPath(attachment);
          if (!path)
            return yield* new ProviderAdapter.ProviderAdapterProtocolError({
              driver: COPILOT_DRIVER,
              detail: "Copilot attachment is unavailable",
              reason: "attachment_unreadable",
            });
          attachments.push({ type: "file" as const, path, displayName: attachment.name });
        }
        history = "";
        const nativeMessageId = yield* sdk(
          "send",
          () =>
            native!.send({
              prompt,
              mode: "immediate",
              agentMode:
                turnInput.runtimePolicy.interactionMode === "plan" ? "plan" : "interactive",
              ...(attachments.length ? { attachments } : {}),
            }),
          30_000,
        ).pipe(
          Effect.tapError(() =>
            Effect.sync(() => {
              active = undefined;
            }),
          ),
        );
        nativeMessageOwners.set(nativeMessageId, turn);
        if (nativeMessageOwners.size > MAX_EXECUTION_ITEMS)
          nativeMessageOwners.delete(nativeMessageOwners.keys().next().value!);
        for (const [fusionId, origin] of pendingFusionOrigins) {
          if (origin === nativeMessageId) {
            pendingFusionOrigins.delete(fusionId);
            yield* bindFusionOwner(fusionId, turn);
          }
        }
        for (const [messageId, message] of pendingFusionMessages) {
          if (message.origin === nativeMessageId) {
            pendingFusionMessages.delete(messageId);
            yield* textEvent(turn, messageId, message.content, true, false);
          }
        }
        turn.accepted = true;
        yield* Queue.offer(inbox, { type: "accepted" });
      });
      return {
        instanceId: input.instanceId,
        driver: COPILOT_DRIVER,
        providerSessionId: open.providerSessionId,
        providerSession,
        events: Stream.fromQueue(events),
        hasPendingBackgroundWork: Effect.sync(() => [...tasks.values()].some(isPendingTask)),
        turnUsageIsContextUsage: false,
        supportsNativeThreadReplacement: false,
        ensureThread,
        resumeThread: (resume) =>
          ensureThread({
            threadId: resume.threadId ?? open.threadId,
            existingProviderThread: resume.providerThread,
            modelSelection: resume.modelSelection ?? open.modelSelection,
            runtimePolicy: resume.runtimePolicy ?? open.runtimePolicy,
          }),
        injectHistory: (context) =>
          Effect.sync(() => {
            history = context.context;
            return true;
          }),
        startTurn,
        steerTurn: (steer) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterSteerRunUnsupportedError({
              driver: COPILOT_DRIVER,
              providerThreadId: steer.providerThread.id,
            }),
          ),
        interruptTurn: Effect.fn("CopilotAdapter.interruptTurn")(function* () {
          if (!native || !active) return;
          active.interrupted = true;
          yield* sdk("abort", () => native!.abort());
        }),
        stopTask: ({ taskId }) =>
          sdk("cancel task", () => native!.rpc.tasks.cancel({ id: taskId })).pipe(Effect.asVoid),
        respondToRuntimeRequest: Effect.fn("CopilotAdapter.respondToRuntimeRequest")(
          function* (response) {
            const entry = pending.get(response.requestId);
            const permissionReplyKey = `${response.decision ?? ""}\n${response.feedback ?? ""}`;
            if (
              !entry &&
              confirmedPermissionReplies.get(response.requestId) === permissionReplyKey &&
              response.answers === undefined
            )
              return;
            if (!entry)
              return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                driver: COPILOT_DRIVER,
                requestId: response.requestId,
              });
            const answer = response.answers?.answer;
            const validAnswer =
              typeof answer === "string" ||
              (Array.isArray(answer) && answer.every((part) => typeof part === "string"));
            if (
              entry.request.kind === "user_input"
                ? !validAnswer
                : !["accept", "decline", "cancel"].includes(response.decision ?? "") ||
                  response.answers !== undefined
            ) {
              return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                driver: COPILOT_DRIVER,
                requestId: response.requestId,
                cause: new Error(
                  "Copilot requires a supported one-time decision or a text answer.",
                ),
              });
            }
            if (entry.responseOwnedByV2) {
              if (!entry.nativePermissionId || entry.permissionReplyKey !== permissionReplyKey) {
                return yield* new ProviderAdapter.ProviderAdapterRuntimeRequestResponseError({
                  driver: COPILOT_DRIVER,
                  requestId: response.requestId,
                });
              }
              if (entry.permissionReplyReceipt)
                return yield* Deferred.await(entry.permissionReplyReceipt);
            }
            // V2 already recorded the answer. Ownership must survive even a failed native receipt.
            entry.responseOwnedByV2 = true;
            const receipt = Deferred.makeUnsafe<void, ProviderAdapter.ProviderAdapterV2Error>();
            if (entry.nativePermissionId) {
              entry.permissionReplyKey = permissionReplyKey;
              entry.permissionReplyReceipt = receipt;
            }
            return yield* Effect.gen(function* () {
              const now = yield* DateTime.now;
              if (entry.nativePermissionId) {
                yield* decidePermission(
                  entry.nativePermissionId,
                  response.decision === "accept"
                    ? { kind: "approve-once" }
                    : {
                        kind: "reject",
                        ...(response.feedback ? { feedback: response.feedback } : {}),
                      },
                );
                confirmedPermissionReplies.set(response.requestId, permissionReplyKey);
              }
              pending.delete(response.requestId);
              entry.owner.items.set(response.requestId, {
                ...entry.item,
                status: "completed",
                completedAt: now,
                updatedAt: now,
              });
              // The decider owns resolution and delivery state; callback handoff is the last operation.
              if (!entry.nativePermissionId) entry.resolve(response);
            }).pipe(
              Effect.onExit((exit) => {
                delete entry.permissionReplyReceipt;
                return Deferred.done(receipt, exit);
              }),
            );
          },
        ),
        readThreadSnapshot: Effect.fn("CopilotAdapter.readThreadSnapshot")(function* () {
          yield* drain();
          if (!providerThread)
            return yield* new ProviderAdapter.ProviderAdapterProtocolError({
              driver: COPILOT_DRIVER,
              detail: "Copilot thread is not loaded",
            });
          return {
            providerThread,
            providerTurns: [...turns.values()],
            messages: [...messages.values()],
            runtimeRequests: [...pending.values()]
              .filter((entry) => !entry.responseOwnedByV2)
              .map((entry) => entry.request),
          };
        }),
        rollbackThread: (rollback) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterRollbackThreadError({
              driver: COPILOT_DRIVER,
              providerThreadId: rollback.providerThread.id,
              cause: new Error("Native Copilot rollback is unsupported."),
            }),
          ),
        forkThread: (fork) =>
          Effect.fail(
            new ProviderAdapter.ProviderAdapterForkThreadError({
              driver: COPILOT_DRIVER,
              providerThreadId: fork.sourceProviderThread.id,
              cause: new Error("Native Copilot fork is unsupported."),
            }),
          ),
      } satisfies ProviderAdapter.ProviderAdapterV2SessionRuntime;
    }),
  });
});

import { ProviderDriverKind, type ServerProviderSkill } from "@t3tools/contracts";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import * as Option from "effect/Option";
import * as ProviderHost from "@t3tools/provider-core/server/ProviderHost";
import * as McpProviderSessions from "@t3tools/provider-core/server/McpProviderSessions";
import type { ProviderDriver, ProviderInstance } from "@t3tools/provider-core/server/driver";
import { ProviderDriverError } from "@t3tools/provider-core/server/errors";
import { makeManagedServerProvider } from "@t3tools/provider-core/server/managedProvider";
import { withInstanceIdentity } from "@t3tools/provider-core/server/instanceIdentity";
import { mergeProviderInstanceEnvironment } from "@t3tools/provider-core/server/instanceEnvironment";
import { makeManualOnlyProviderMaintenanceCapabilities } from "@t3tools/provider-core/server/maintenanceResolver";
import {
  haveProviderSnapshotSettingsChanged,
  makeProviderSnapshotSettingsSource,
} from "@t3tools/provider-core/server/snapshotSettings";
import { CopilotSettings } from "../settings.ts";
import { makeAdapter } from "./adapter.ts";
import { createClient, resolveClientConfiguration } from "./client.ts";
import { checkStatus, filterModelsForSettings, pendingSnapshot, skillsFromSdk } from "./status.ts";
import { makeTextGeneration } from "./textGeneration.ts";

const driverKind = ProviderDriverKind.make("githubCopilot");
const decodeSettings = Schema.decodeSync(CopilotSettings);
export type CopilotDriverEnv = ProviderHost.ProviderHost | McpProviderSessions.McpProviderSessions;

export const CopilotDriver: ProviderDriver<CopilotSettings, CopilotDriverEnv> = {
  driverKind,
  metadata: { displayName: "GitHub Copilot", supportsMultipleInstances: true },
  configSchema: CopilotSettings,
  defaultConfig: () => decodeSettings({}),
  create: Effect.fn("CopilotDriver.create")(function* ({
    instanceId,
    displayName,
    accentColor,
    environment,
    enabled,
    config,
  }) {
    const host = yield* ProviderHost.ProviderHost;
    const processEnv = yield* mergeProviderInstanceEnvironment(environment);
    const settings = { ...config, enabled };
    const configuration = yield* Effect.try({
      try: () =>
        resolveClientConfiguration({ settings, cwd: host.paths.cwd, environment: processEnv }),
      catch: (cause) =>
        new ProviderDriverError({
          driver: driverKind,
          instanceId,
          detail: "Could not configure Copilot.",
          cause,
        }),
    });
    const continuationIdentity = {
      driverKind,
      continuationKey: `githubCopilot:home:${configuration.effectiveHome}`,
    };
    const stamp = withInstanceIdentity({
      instanceId,
      driverKind,
      displayName,
      accentColor,
      continuationGroupKey: continuationIdentity.continuationKey,
    });
    const workspaceSkills = new Map<string, ReadonlyArray<ServerProviderSkill>>();
    const orchestrationAdapter = yield* makeAdapter(
      { instanceId, settings, environment: processEnv },
      {
        onSkills: (cwd, skills) => {
          if (skills) workspaceSkills.set(cwd, skills);
          else workspaceSkills.delete(cwd);
        },
      },
    );
    const snapshotSettings = yield* makeProviderSnapshotSettingsSource(settings);
    const snapshot = yield* makeManagedServerProvider({
      resolveMaintenance: () =>
        Effect.succeed(
          makeManualOnlyProviderMaintenanceCapabilities({
            provider: driverKind,
            packageName: "@github/copilot-sdk",
          }),
        ),
      getSettings: snapshotSettings.getSettings,
      streamSettings: snapshotSettings.streamSettings,
      haveSettingsChanged: haveProviderSnapshotSettingsChanged,
      initialSnapshot: () => pendingSnapshot(settings).pipe(Effect.map(stamp)),
      checkProvider: checkStatus(settings, host.paths.cwd, processEnv).pipe(Effect.map(stamp)),
    }).pipe(
      Effect.mapError(
        (cause) =>
          new ProviderDriverError({
            driver: driverKind,
            instanceId,
            detail: "Could not build Copilot provider snapshot.",
            cause,
          }),
      ),
    );
    const snapshotForCwd: NonNullable<ProviderInstance["snapshotForCwd"]> = Effect.fn(
      "CopilotDriver.snapshotForCwd",
    )(function* (cwd) {
      const current = yield* snapshot.getSnapshot;
      if (!enabled) return current;
      const cached = workspaceSkills.get(cwd);
      if (cached) return { ...current, skills: cached };
      const skills = yield* Effect.scoped(
        Effect.gen(function* () {
          const client = yield* Effect.acquireRelease(
            Effect.try({
              try: () =>
                createClient(
                  resolveClientConfiguration({ settings, cwd, environment: processEnv }).options,
                ),
              catch: (cause) =>
                new ProviderDriverError({
                  driver: driverKind,
                  instanceId,
                  detail: "Copilot discovery failed.",
                  cause,
                }),
            }),
            (client) =>
              Effect.gen(function* () {
                const stopped = yield* Effect.tryPromise(() => client.stop()).pipe(
                  Effect.timeoutOption(10_000),
                  Effect.result,
                );
                if (
                  stopped._tag === "Failure" ||
                  Option.isNone(stopped.success) ||
                  stopped.success.value.length
                ) {
                  yield* Effect.tryPromise(() => client.forceStop()).pipe(
                    Effect.timeoutOption(5_000),
                    Effect.ignore,
                  );
                }
              }),
          );
          return yield* Effect.tryPromise({
            try: async () => {
              await client.start();
              const discovered = await client.rpc.skills.discover({
                projectPaths: settings.enableConfigDiscovery ? [cwd] : [],
              });
              return skillsFromSdk(discovered.skills);
            },
            catch: (cause) =>
              new ProviderDriverError({
                driver: driverKind,
                instanceId,
                detail: "Copilot workspace skill discovery failed.",
                cause,
              }),
          });
        }),
      ).pipe(
        Effect.timeoutOption(30_000),
        Effect.flatMap((result) =>
          Effect.fromOption(result).pipe(
            Effect.mapError(
              (cause) =>
                new ProviderDriverError({
                  driver: driverKind,
                  instanceId,
                  detail: "Copilot discovery timed out.",
                  cause,
                }),
            ),
          ),
        ),
      );
      return { ...current, skills };
    });
    return {
      instanceId,
      driverKind,
      displayName,
      accentColor,
      enabled,
      continuationIdentity,
      snapshot,
      filterModels: (models) => filterModelsForSettings(models, settings),
      snapshotForCwd,
      orchestrationAdapter,
      textGeneration: makeTextGeneration(settings, processEnv),
    } satisfies ProviderInstance;
  }),
};

import { assert, describe, it } from "@effect/vitest";
import type { ModelInfo, SkillsLoadedSkill } from "@github/copilot-sdk";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import { CopilotSettings } from "../settings.ts";
import { checkStatus, modelsFromSdk, skillsFromSdk } from "./status.ts";
import { bundledCliPath, resolveClientConfiguration } from "./client.ts";
import type { AutoCatalog } from "./routing.ts";

const decode = Schema.decodeSync(CopilotSettings);
const model = (id: string, extra: Partial<ModelInfo> = {}): ModelInfo => ({
  id,
  name: id,
  capabilities: {
    supports: { vision: true, reasoningEffort: true },
    limits: { max_context_window_tokens: 128_000 },
  },
  ...extra,
});
const skill = (
  name: string,
  source: SkillsLoadedSkill["source"],
  extra: Partial<SkillsLoadedSkill> = {},
): SkillsLoadedSkill => ({
  name,
  source,
  description: `${name} skill`,
  enabled: true,
  userInvocable: true,
  path: `/workspace/${name}/SKILL.md`,
  ...extra,
});

describe("Copilot discovery and account isolation", () => {
  it("opts in per subprocess, preserving unrelated flags and leaving the default environment alone", () => {
    const environment = {
      HOME: "/private",
      COPILOT_CLI_ENABLED_FEATURE_FLAGS: "EXTENSIONS,DYNAMIC_AUTO_TIERS",
    };
    assert.isFalse(decode({}).enableFusion);
    const disabled = resolveClientConfiguration({
      settings: decode({}),
      cwd: "/workspace",
      environment,
    });
    assert.equal(
      disabled.options.env?.COPILOT_CLI_ENABLED_FEATURE_FLAGS,
      "EXTENSIONS,DYNAMIC_AUTO_TIERS",
    );
    const enabled = resolveClientConfiguration({
      settings: decode({ enableFusion: true }),
      cwd: "/workspace",
      environment,
    });
    assert.equal(
      enabled.options.env?.COPILOT_CLI_ENABLED_FEATURE_FLAGS,
      "EXTENSIONS,DYNAMIC_AUTO_TIERS,HYDRAFUSION_PLAN_V2",
    );
    assert.equal(environment.COPILOT_CLI_ENABLED_FEATURE_FLAGS, "EXTENSIONS,DYNAMIC_AUTO_TIERS");
  });
  it("adds advertised Auto routing without replacing explicit-model defaults", () => {
    const auto: AutoCatalog = {
      defaultTier: "opaque-tier",
      tiers: [
        {
          id: "opaque-tier",
          displayName: "Fusion",
          description: "Account supplied",
          type: "fusion",
          status: { enabled: true },
        },
      ],
    };
    const result = modelsFromSdk([model("explicit")], decode({}), auto);
    assert.deepEqual(
      result.map((entry) => entry.slug),
      ["explicit", "auto"],
    );
    assert.isTrue(result[0]?.isDefault);
    assert.isUndefined(result[1]?.isDefault);
    assert.equal(result[1]?.capabilities?.optionDescriptors?.[0]?.id, "autoTier");
    assert.equal(result[1]?.name, "Fusion");
    assert.equal(result[1]?.capabilities?.optionDescriptors?.[0]?.label, "Fusion effort");
    assert.deepEqual(
      modelsFromSdk([model("explicit")], decode({})).map((entry) => entry.slug),
      ["explicit"],
    );
  });
  it("keeps advertised plain Auto without tier metadata or invented routing choices", () => {
    const result = modelsFromSdk([model("explicit"), model("auto")], decode({}));
    assert.deepEqual(
      result.map((entry) => entry.slug),
      ["explicit", "auto"],
    );
    assert.isTrue(result[0]?.isDefault);
    assert.isUndefined(result[1]?.isDefault);
    assert.deepEqual(result[1]?.capabilities?.optionDescriptors, []);
    assert.equal(result[1]?.name, "auto");
    assert.deepEqual(
      modelsFromSdk([model("auto", { policy: { state: "disabled", terms: "" } })], decode({})),
      [],
    );
    assert.deepEqual(modelsFromSdk([], decode({})), []);
  });

  it("keeps project/native skills in workspace results, including pathless built-ins", () => {
    const skills = skillsFromSdk([
      skill("project-skill", "project"),
      skill("personal-skill", "personal-copilot"),
      skill("builtin", "builtin", { path: "" }),
      skill("disabled", "project", { enabled: false }),
      skill("agent-only", "project", { userInvocable: false }),
      skill("project-skill", "personal-agents"),
    ]);
    assert.deepEqual(
      skills.map((entry) => entry.name),
      ["project-skill", "personal-skill", "builtin"],
    );
    assert.equal(skills[0]?.scope, "project");
    assert.equal(skills[2]?.path, "copilot://skills/builtin");
  });

  it("discovers allowed models and reasoning options without duplicates or policy-disabled models", () => {
    const result = modelsFromSdk(
      [
        model("internal", { name: "Fixture model (Internal only)" }),
        model("gpt", {
          supportedReasoningEfforts: ["low", "high"],
          defaultReasoningEffort: "high",
        }),
        model("gpt"),
        model("custom", { name: "Configured model (INTERNAL ONLY)" }),
        model("blocked", { policy: { state: "disabled", terms: "" } }),
      ],
      decode({ customModels: ["custom"] }),
    );
    assert.deepEqual(
      result.map((entry) => entry.slug),
      ["internal", "gpt", "custom"],
    );
    assert.deepEqual(result[1]?.capabilities?.optionDescriptors?.[0], {
      id: "reasoningEffort",
      label: "Reasoning",
      type: "select",
      currentValue: "high",
      options: [
        { id: "low", label: "Low" },
        { id: "high", label: "High", isDefault: true },
      ],
    });
    const filtered = modelsFromSdk(
      [
        model("internal", { name: "Fixture model (Internal only)" }),
        model("gpt"),
        model("custom", { name: "Configured model (INTERNAL ONLY)" }),
        model("blocked", { policy: { state: "disabled", terms: "" } }),
      ],
      decode({ customModels: ["custom"], hideInternalModels: true }),
    );
    assert.deepEqual(
      filtered.map((entry) => entry.slug),
      ["gpt", "custom"],
    );
    assert.isTrue(filtered[0]?.isDefault);
  });

  it("uses only the selected account's home and preserves SDK-owned native paths", () => {
    const first = resolveClientConfiguration({
      settings: decode({ homePath: "~/.copilot-work" }),
      cwd: "/workspace",
      environment: { HOME: "/accounts/first", COPILOT_HOME: "/ignored", GITHUB_TOKEN: "first" },
    });
    const second = resolveClientConfiguration({
      settings: decode({}),
      cwd: "/workspace",
      environment: { HOME: "/accounts/second", COPILOT_HOME: "/native/second" },
    });
    assert.equal(first.effectiveHome, "/accounts/first/.copilot-work");
    assert.equal(first.options.mode, "copilot-cli");
    assert.equal(first.options.baseDirectory, first.effectiveHome);
    assert.equal(first.options.env?.COPILOT_HOME, first.effectiveHome);
    assert.equal(second.effectiveHome, "/native/second");
    assert.isUndefined(second.options.env?.GITHUB_TOKEN);
  });

  it("resolves packaged Windows executables outside asar and Linux libc alternatives", () => {
    assert.equal(
      bundledCliPath({
        packaged: true,
        electron: true,
        platform: "win32",
        architecture: "x64",
        resolve: () =>
          "C:\\T3\\app.asar\\node_modules\\@github\\copilot-sdk-win32-x64\\package.json",
        exists: (path) => path.includes("app.asar.unpacked"),
      }),
      "C:\\T3\\app.asar.unpacked\\node_modules\\@github\\copilot-sdk-win32-x64\\prebuilds\\win32-x64\\copilot-runtime.exe",
    );
    assert.equal(
      bundledCliPath({
        packaged: true,
        electron: false,
        platform: "linux",
        architecture: "arm64",
        resolve: (name) => {
          if (!name.includes("linuxmusl")) throw new Error("not installed");
          return "/native/package.json";
        },
        exists: () => true,
      }),
      "/native/prebuilds/linuxmusl-arm64/copilot-runtime",
    );
    assert.throws(() =>
      bundledCliPath({
        packaged: true,
        electron: false,
        platform: "darwin",
        architecture: "arm64",
        resolve: () => "/native/package.json",
        exists: (path) => !path.endsWith("runtime.node"),
      }),
    );
  });

  it.effect("returns authenticated SDK models without exposing any workspace skills globally", () =>
    Effect.gen(function* () {
      let stops = 0;
      const result = yield* checkStatus(
        decode({ enabled: true }),
        "/workspace",
        { HOME: "/account" },
        () => ({
          start: async () => {},
          stop: async () => {
            stops++;
            return [];
          },
          forceStop: async () => {},
          getStatus: async () => ({ version: "1.0.75", protocolVersion: 1 }),
          getAuthStatus: async () => ({ isAuthenticated: true, login: "octocat" }),
          rpc: { models: { list: async () => ({ models: [model("gpt"), model("auto")] }) } },
        }),
      );
      assert.equal(result.status, "ready");
      assert.equal(result.auth.label, "octocat");
      assert.equal(result.models[0]?.slug, "gpt");
      assert.equal(result.models[1]?.slug, "auto");
      assert.equal(
        result.message,
        "This account/runtime does not advertise routing preferences. Available models can still use their default routing.",
      );
      assert.deepEqual(result.skills, []);
      assert.equal(stops, 1);
    }),
  );

  it.effect(
    "reports cleanup-only failures and preserves a primary probe failure when cleanup also fails",
    () =>
      Effect.gen(function* () {
        for (const failProbe of [false, true]) {
          let forced = 0;
          const snapshot = yield* checkStatus(decode({ enabled: true }), "/workspace", {}, () => ({
            start: async () => {},
            stop: async () => {
              throw new Error("stop failed");
            },
            forceStop: async () => {
              forced++;
            },
            getStatus: async () => {
              if (failProbe) throw new Error("probe failed");
              return { version: "1.0.75", protocolVersion: 1 };
            },
            getAuthStatus: async () => ({ isAuthenticated: true }),
            rpc: { models: { list: async () => ({ models: [] }) } },
          }));
          assert.equal(snapshot.status, "error");
          assert.equal(forced, 1);
          assert.equal(
            snapshot.message,
            failProbe ? "GitHub Copilot status check failed." : "GitHub Copilot cleanup failed.",
          );
        }
      }),
  );
});

import type { CopilotClient, SkillsLoadedSkill } from "@github/copilot-sdk";
import type { ServerProvider, ServerProviderSkill } from "@t3tools/contracts";
import { createModelCapabilities, readCustomModelEntries } from "@t3tools/shared/model";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import {
  buildSelectOptionDescriptor,
  buildServerProvider,
  providerModelsFromSettings,
} from "@t3tools/provider-core/server/snapshotProbe";
import type { CopilotSettings } from "../settings.ts";
import { createClient, resolveClientConfiguration } from "./client.ts";
import { routingDescriptor, type AutoCatalog, type ModelCatalog } from "./routing.ts";

const presentation = {
  displayName: "GitHub Copilot",
  badgeLabel: "Preview",
  showInteractionModeToggle: true,
  supportsConversationRollback: false,
};
const emptyCapabilities = createModelCapabilities({ optionDescriptors: [] });

export function filterModelsForSettings(
  models: ServerProvider["models"],
  settings: CopilotSettings,
): ServerProvider["models"] {
  if (!settings.hideInternalModels) return models;
  const customSlugs = new Set(
    readCustomModelEntries(settings.customModels).map(({ slug }) => slug),
  );
  const visible = models.filter(
    (model) =>
      model.isCustom ||
      customSlugs.has(model.slug) ||
      !model.name.toLowerCase().includes("internal only"),
  );
  return visible.length === models.length
    ? models
    : visible.map((model, index) => ({ ...model, isDefault: index === 0 }));
}

export function modelsFromSdk(
  models: ReadonlyArray<ModelCatalog["models"][number]>,
  settings: CopilotSettings,
  auto?: AutoCatalog,
) {
  const seen = new Set<string>();
  const autoName = auto?.tiers.some((tier) => tier.type === "fusion") ? "Fusion" : undefined;
  return filterModelsForSettings(
    providerModelsFromSettings(
      models
        .flatMap((model) => {
          const slug = model.id.trim();
          if (!slug || !model.name.trim() || seen.has(slug) || model.policy?.state === "disabled")
            return [];
          seen.add(slug);
          const efforts = model.supportedReasoningEfforts ?? [];
          const routing = slug === "auto" && auto ? routingDescriptor(auto) : undefined;
          return [
            {
              slug,
              name: slug === "auto" && autoName ? autoName : model.name,
              isCustom: false,
              ...(seen.size === 1 ? { isDefault: true } : {}),
              capabilities: createModelCapabilities({
                optionDescriptors: [
                  ...(routing ? [routing] : []),
                  ...(efforts.length
                    ? [
                        buildSelectOptionDescriptor({
                          id: "reasoningEffort",
                          label: "Reasoning",
                          options: efforts.map((effort) => ({
                            value: effort,
                            label:
                              effort === "xhigh"
                                ? "Extra High"
                                : effort[0]!.toUpperCase() + effort.slice(1),
                            isDefault: effort === model.defaultReasoningEffort,
                          })),
                        }),
                      ]
                    : []),
                ],
              }),
            },
          ];
        })
        .concat(
          auto && !seen.has("auto") && !models.some((model) => model.id.trim() === "auto")
            ? [
                {
                  slug: "auto",
                  name: autoName ?? "Auto routing",
                  isCustom: false,
                  capabilities: createModelCapabilities({
                    optionDescriptors: [routingDescriptor(auto)],
                  }),
                },
              ]
            : [],
        ),
      settings.customModels,
      emptyCapabilities,
    ),
    settings,
  );
}

// Workspace snapshots are requested with a cwd; no project skills enter the instance snapshot.
export function skillsFromSdk(
  skills: ReadonlyArray<SkillsLoadedSkill>,
): ReadonlyArray<ServerProviderSkill> {
  const seen = new Set<string>();
  return skills.flatMap((skill) => {
    const name = skill.name.trim();
    if (!name || !skill.enabled || !skill.userInvocable || seen.has(name)) return [];
    seen.add(name);
    return [
      {
        name,
        ...(skill.description.trim() ? { description: skill.description } : {}),
        path: skill.path?.trim() || `copilot://skills/${encodeURIComponent(name)}`,
        enabled: true,
        scope: skill.source,
        userInvocable: true,
      },
    ];
  });
}

export const pendingSnapshot = (settings: CopilotSettings) =>
  DateTime.now.pipe(
    Effect.map((now) =>
      buildServerProvider({
        presentation,
        enabled: settings.enabled,
        checkedAt: DateTime.formatIso(now),
        models: modelsFromSdk([], settings),
        probe: {
          installed: false,
          version: null,
          status: "warning",
          auth: { status: "unknown" },
          message: settings.enabled
            ? "Checking GitHub Copilot availability..."
            : "GitHub Copilot is disabled.",
        },
      }),
    ),
  );

export type StatusClient = Pick<
  CopilotClient,
  "start" | "stop" | "forceStop" | "getStatus" | "getAuthStatus"
> & { readonly rpc: { readonly models: Pick<CopilotClient["rpc"]["models"], "list"> } };

export const checkStatus = Effect.fn("Copilot.checkStatus")(function* (
  settings: CopilotSettings,
  cwd: string,
  environment: NodeJS.ProcessEnv,
  factory: (
    options: ReturnType<typeof resolveClientConfiguration>["options"],
  ) => StatusClient = createClient,
) {
  if (!settings.enabled) return yield* pendingSnapshot(settings);
  let started = false;
  let cleanupFailed = false;
  const checkedAt = DateTime.formatIso(yield* DateTime.now);
  const result = yield* Effect.scoped(
    Effect.gen(function* () {
      const client = yield* Effect.acquireRelease(
        Effect.try(() =>
          factory(resolveClientConfiguration({ settings, cwd, environment }).options),
        ),
        (client) =>
          Effect.gen(function* () {
            const stopped = yield* Effect.tryPromise(() => client.stop()).pipe(
              Effect.timeoutOption(10_000),
              Effect.result,
            );
            if (
              stopped._tag === "Failure" ||
              Option.isNone(stopped.success) ||
              stopped.success.value.length
            ) {
              cleanupFailed = true;
              yield* Effect.tryPromise(() => client.forceStop()).pipe(
                Effect.timeoutOption(5_000),
                Effect.ignore,
              );
            }
          }),
      );
      return yield* Effect.tryPromise(async () => {
        await client.start();
        started = true;
        const [status, auth] = await Promise.all([client.getStatus(), client.getAuthStatus()]);
        const catalog = auth.isAuthenticated ? await client.rpc.models.list({}) : { models: [] };
        return { status, auth, catalog };
      });
    }),
  ).pipe(Effect.timeoutOption(30_000), Effect.result);
  if (result._tag === "Failure" || Option.isNone(result.success) || cleanupFailed) {
    return buildServerProvider({
      presentation,
      enabled: true,
      checkedAt,
      models: modelsFromSdk([], settings),
      probe: {
        installed: started,
        version: null,
        status: "error",
        auth: { status: "unknown" },
        message:
          cleanupFailed && result._tag === "Success" && Option.isSome(result.success)
            ? "GitHub Copilot cleanup failed."
            : started
              ? "GitHub Copilot status check failed."
              : "Unable to start the Copilot CLI.",
      },
    });
  }
  const { status, auth, catalog } = result.success.value;
  return buildServerProvider({
    presentation,
    enabled: true,
    checkedAt,
    models: modelsFromSdk(catalog.models, settings, catalog.auto),
    probe: {
      installed: true,
      version: status.version,
      status: auth.isAuthenticated ? "ready" : "error",
      auth: auth.isAuthenticated
        ? { status: "authenticated", ...(auth.login ? { label: auth.login } : {}) }
        : { status: "unauthenticated" },
      ...(!auth.isAuthenticated
        ? { message: "Sign in with `copilot login` in this provider's account environment." }
        : !catalog.auto
          ? {
              message:
                "This account/runtime does not advertise routing preferences. Available models can still use their default routing.",
            }
          : {}),
    },
  });
});

